class Solution:
    def numDecodings(self, s: str) -> int:
        if not s:
            return 0

        n = len(s)
        if s[0] == '0':
            return 0

        dp = [0] * (n + 1)
        dp[0] = 1
        dp[1] = 1

        for i in range(2, n + 1):
            digit = s[i - 1]
            two_digits = s[i - 2:i]

            if digit != '0':
                dp[i] += dp[i - 1]

            if two_digits[0] == '1' or (two_digits[0] == '2' and '0' <= two_digits[1] <= '6'):
                dp[i] += dp[i - 2]

        return dp[n]
